<script setup>
import {ref,computed,toRaw} from 'vue'
import {Button,FormControl,Badge,Avatar,FeatherIcon,ErrorMessage} from 'frappe-ui'
import {threadData,teamData,flowData} from './data'
const mobileChat=ref(false), showDetails=ref(false)
const view=ref('Inbox'),threads=ref(structuredClone(threadData)),teams=ref(structuredClone(teamData)),nodes=ref(structuredClone(flowData)),active=ref('c1'),draft=ref(''),search=ref(''),filter=ref('All'),note=ref(false),team=ref(null),original=ref(''),error=ref(''),saved=ref(''),selected=ref(1),flowOpen=ref(false),published=ref(false)
const current=computed(()=>threads.value.find(t=>t.id===active.value)),rows=computed(()=>threads.value.filter(t=>t.name.toLowerCase().includes(search.value.toLowerCase())&&(filter.value!=='Unassigned'||t.assignee==='Unassigned')&&(filter.value!=='Uncategorized'||!t.contact))),node=computed(()=>nodes.value.find(n=>n.id===selected.value))
function nav(v){view.value=v;error.value='';saved.value=''}
function edit(t){team.value=structuredClone(toRaw(t));original.value=t.name;error.value='';saved.value=''}
function save(){error.value='';if(!team.value.name.trim())return error.value='Team name is required.';if(!team.value.members.some(m=>m.role==='Manager'))return error.value='Add at least one manager.';if(!team.value.channels.length)return error.value='Select at least one channel.';if(teams.value.some(t=>t.name===team.value.name&&t.name!==original.value))return error.value='Team name already exists.';const i=teams.value.findIndex(t=>t.name===original.value);if(i<0)teams.value.push(structuredClone(toRaw(team.value)));else teams.value[i]=structuredClone(toRaw(team.value));threads.value.filter(t=>t.team===original.value).forEach(t=>t.team=team.value.name);original.value=team.value.name;saved.value='Saved'}
function send(){if(!draft.value.trim())return;current.value.messages.push({who:note.value?'You · Note':'You',text:draft.value,time:'Now',out:true,note:note.value});draft.value=''}
function saveFlow(p){error.value='';if(nodes.value.some(n=>!n.value.trim()))return error.value='Complete all node fields.';if(!nodes.value[0].value.startsWith('/'))return error.value='Command must start with /.';published.value=p;saved.value=p?'Published':'Draft saved'}
</script>
<template><div class="app-shell"><aside class="app-nav"><div class="flex items-center gap-2 px-2 py-5 mb-4"><FeatherIcon name="message-circle" class="h-6 w-6"/><strong class="nav-label">Communication</strong></div><button v-for="[v,icon] in [['Inbox','inbox'],['Flows','git-branch'],['Teams','users']]" :key="v" class="nav-item" :class="{active:view===v}" @click="nav(v)"><FeatherIcon :name="icon" class="h-4 w-4"/><span class="nav-label">{{v}}</span></button><div class="mt-auto flex items-center gap-2 p-2 border-t"><Avatar label="Sakthi"/><span class="nav-label text-sm">Sakthi</span></div></aside><main class="workspace"><header class="page-header"><strong class="text-base">{{view}}<span v-if="view==='Flows'&&flowOpen" class="text-ink-gray-4"> / Order status</span></strong><Badge label="Preview"/><div class="ml-auto flex items-center gap-2"><span role="status" class="text-sm text-ink-gray-5">{{saved}}</span><template v-if="view==='Teams'"><Button v-if="team" label="Save" variant="solid" @click="save"/><Button v-else label="New team" variant="solid" icon-left="plus" @click="edit({name:'',members:[{name:'Sakthi',role:'Manager'}],channels:[]})"/></template><template v-if="view==='Flows'&&flowOpen"><Badge :label="published?'Published':'Draft'"/><Button label="Save draft" @click="saveFlow(false)"/><Button label="Publish" variant="solid" @click="saveFlow(true)"/></template></div></header>
<template v-if="view==='Inbox'"><div class="toolbar"><Button v-for="f in ['All','Unassigned','Uncategorized']" :key="f" :label="f" :variant="filter===f?'subtle':'ghost'" @click="filter=f"/><div class="ml-auto w-48"><FormControl v-model="search" placeholder="Search conversations" aria-label="Search conversations"/></div></div><div class="inbox-grid flex-1 min-h-0" :class="{'mobile-chat':mobileChat}"><section class="conversation-list"><button v-for="t in rows" :key="t.id" class="conversation-item w-full text-left" :class="{selected:active===t.id}" @click="active=t.id;draft='';mobileChat=true "><div class="flex gap-2 items-center"><Avatar :label="t.name"/><strong class="text-base truncate">{{t.name}}</strong><span class="ml-auto text-xs text-ink-gray-4">{{t.time}}</span></div><p class="text-sm text-ink-gray-5 truncate my-2">{{t.messages.at(-1).text}}</p><div class="flex justify-between"><Badge :label="t.channel"/><span class="text-xs text-ink-gray-5">{{t.team}}</span></div></button><p v-if="!rows.length" class="p-5 text-sm">No conversations</p></section><section class="thread-panel"><div class="flex items-center gap-2 px-4 h-14 border-b shrink-0"><Button class="mobile-only" icon="arrow-left" aria-label="Back to conversations" @click="mobileChat=false"/><strong class="text-base">{{current.name}}</strong><Badge :label="current.status"/><Button class="ml-auto" :label="current.status==='Open'?'Resolve':'Reopen'" @click="current.status=current.status==='Open'?'Resolved':'Open'"/><Button class="details-toggle" icon="sidebar" aria-label="Show details" @click="showDetails=!showDetails"/></div><div class="message-scroll"><p class="text-center text-xs text-ink-gray-4 my-5">Today</p><p v-if="current.subject" class="font-medium mb-4">{{current.subject}}</p><div v-for="(m,i) in current.messages" :key="i" class="flex flex-col mb-5" :class="{'items-end':m.out}"><div class="text-xs text-ink-gray-5 mb-1">{{m.who}} · {{m.time}}</div><div class="message-body whitespace-pre-wrap" :class="{outgoing:m.out,note:m.note}">{{m.text}}</div></div></div><div class="composer"><div class="flex items-center gap-2 px-3 pt-2"><Button label="Reply" :variant="note?'ghost':'subtle'" @click="note=false"/><Button label="Note" :variant="note?'subtle':'ghost'" @click="note=true"/><span class="ml-auto text-xs text-ink-gray-5">{{note?'Internal':current.channel}}</span></div><div class="p-3"><FormControl v-model="draft" type="textarea" :rows="3" :placeholder="note?'Write a note…':'Write a reply…'" aria-label="Message"/></div><div class="flex justify-end px-3 pb-3"><Button :label="note?'Add note':'Send'" variant="solid" :disabled="!draft.trim()" @click="send"/></div></div></section><aside class="details-panel" :class="{'details-open':showDetails}"><div class="flex items-center justify-between"><strong class="text-sm">Conversation</strong><Button class="details-toggle" icon="x" aria-label="Close details" @click="showDetails=false"/></div><FormControl label="Team" type="select" :options="teams.filter(t=>t.channels.includes(current.channel)).map(t=>t.name)" v-model="current.team" @update:modelValue="current.assignee='Unassigned'"/><FormControl label="Assignee" type="select" :options="['Unassigned','You',...(teams.find(t=>t.name===current.team)?.members.map(m=>m.name)||[])]" v-model="current.assignee"/><div><div class="field-label mb-2">Handled by</div><div class="flex justify-between items-center"><span class="text-sm">{{current.bot?'Assistant':'Human'}}</span><Button :label="current.bot?'Take over':'Resume bot'" @click="current.bot=!current.bot;current.assignee=current.bot?'Unassigned':'You'"/></div></div><hr/><strong class="text-sm block">Contact</strong><Avatar :label="current.name" size="lg"/><div class="text-base">{{current.name}}</div><Badge :label="current.contact?'Linked':'Uncategorized'"/><div class="field-label">Channel</div><div class="text-sm">{{current.channel}}</div></aside></div></template>
<div v-else-if="view==='Teams'" class="page-body"><template v-if="!team"><table class="list-table"><thead><tr><th>Team</th><th>Members</th><th>Channels</th><th></th></tr></thead><tbody><tr v-for="t in teams" :key="t.name"><td>{{t.name}}</td><td>{{t.members.length}}</td><td><Badge v-for="c in t.channels" :key="c" :label="c" class="mr-1"/></td><td><Button :label="'Edit '+t.name" @click="edit(t)"/></td></tr></tbody></table></template><div v-else class="form-page"><Button label="Teams" icon-left="arrow-left" variant="ghost" @click="team=null;error='';saved=''"/><h2 class="text-xl font-semibold">{{original||'New team'}}</h2><FormControl label="Team name" required v-model="team.name"/><section><h3 class="font-medium mb-3">Channels</h3><div class="flex gap-5"><FormControl v-for="c in ['WhatsApp','Email','Telegram']" :key="c" type="checkbox" :label="c" :model-value="team.channels.includes(c)" @update:modelValue="v=>team.channels=v?[...team.channels,c]:team.channels.filter(x=>x!==c)"/></div></section><section><h3 class="font-medium mb-3">Members</h3><div v-for="(m,i) in team.members" :key="m.name" class="flex items-center gap-3 mb-4"><Avatar :label="m.name"/><span class="text-base flex-1">{{m.name}}</span><FormControl type="select" :aria-label="'Role for '+m.name" :options="['Manager','Agent']" v-model="m.role"/><Button icon="x" :aria-label="'Remove '+m.name" @click="team.members.splice(i,1)"/></div><FormControl label="Add member" type="select" :model-value="''" :options="[{label:'Select a member',value:''},...['Sakthi','Priya N.','Ravi M.','Meera S.','Arun D.'].filter(n=>!team.members.some(m=>m.name===n))]" @update:modelValue="v=>{if(v)team.members.push({name:v,role:'Agent'})}"/></section><ErrorMessage :message="error"/></div></div>
<template v-else><div v-if="!flowOpen" class="page-body"><table class="list-table"><thead><tr><th>Name</th><th>Channels</th><th>Trigger</th><th>Status</th><th></th></tr></thead><tbody><tr><td>Order status</td><td><Badge label="WhatsApp" class="mr-1"/><Badge label="Telegram"/></td><td>/order</td><td><Badge :label="published?'Published':'Draft'"/></td><td><Button label="Edit flow" @click="flowOpen=true"/></td></tr></tbody></table></div><div v-else class="flow-layout flex-1 min-h-0"><div class="flow-canvas"><Button label="Flows" icon-left="arrow-left" @click="flowOpen=false"/><div class="flex flex-col items-center py-6"><template v-for="(n,i) in nodes" :key="n.id"><div v-if="i" class="flow-edge h-7"></div><button class="flow-node text-left" :class="{selected:selected===n.id}" @click="selected=n.id"><div class="flex gap-2 items-center text-xs text-ink-gray-5 mb-2"><FeatherIcon :name="n.icon" class="h-4 w-4"/>{{n.type}}</div><div class="text-base font-medium">{{n.label}}</div></button></template></div></div><aside class="flow-inspector space-y-5"><h2 class="text-base font-semibold">{{node.type}}</h2><FormControl label="Label" v-model="node.label" @update:modelValue="published=false;saved=''"/><FormControl :label="node.field" required :type="['Reply','Ask'].includes(node.type)?'textarea':'text'" v-model="node.value" @update:modelValue="published=false;saved=''"/><ErrorMessage :message="error"/></aside></div></template>
</main></div></template>
